import React, { useState } from "react";
import "./BuySearchBar.css";

export default function BuySearchBar({ onResults }) {
  const [state, setState] = useState("");
  const [district, setDistrict] = useState("");
  const [city, setCity] = useState("");

  const doSearch = async () => {
    const params = new URLSearchParams();
    if (state) params.append("state", state);
    if (district) params.append("district", district);
    if (city) params.append("city", city);

    try {
      const url = `${process.env.REACT_APP_BACKEND_URL}/buy/search?${params.toString()}`;
      const res = await fetch(url);
      if (!res.ok) throw new Error("Search failed");
      const data = await res.json();
      onResults(data);
    } catch (e) {
      onResults([]);
      alert("Unable to fetch listings for the selected location.");
    }
  };

  return (
    <div className="buy-search-card">
      <h3 className="buy-search-title">Find Properties by Location</h3>
      <div className="buy-search-row">
        <select value={state} onChange={(e) => setState(e.target.value)}>
          <option value="">Select State</option>
          <option>Tamil Nadu</option>
          {/* Add more states as needed */}
        </select>
      </div>
      <div className="buy-search-row">
        <select value={district} onChange={(e) => setDistrict(e.target.value)}>
          <option value="">Select District</option>
          <option>Madurai</option>
          {/* Populate based on state if needed */}
        </select>
      </div>
      <div className="buy-search-row search-input-wrap">
        <input
          type="text"
          placeholder="City"
          value={city}
          onChange={(e) => setCity(e.target.value)}
        />
        <button className="finder-btn" type="button" onClick={doSearch} title="Search">
          🔍
        </button>
      </div>
    </div>
  );
}
